DEFAULT_MODEL = os.environ.get("OPENAI_MODEL", "gpt-6-astra")


def _client():
    from openai import OpenAI

    return OpenAI()


def available() -> bool:
    return bool(os.environ.get("OPENAI_API_KEY"))


def complete(prompt: str, *, model: str | None = None, effort: str = "medium") -> str:
    response = _client().responses.create(
        model=model or DEFAULT_MODEL,
        input=prompt,
        reasoning={"effort": effort},
    )
    return response.output_text


def complete_json(prompt: str, *, model: str | None = None, effort: str = "low") -> Any:
    text = complete(
        prompt + "\n\nReply with a single JSON object or array. No markdown.",
        model=model,
        effort=effort,
    )
    text = text.strip()
    fence = re.search(r"```(?:json)?\s*([\s\S]*?)```", text)
    if fence:
        text = fence.group(1).strip()
    return json.loads(text)

