        z = max(-2.0, min(2.0, z))  # confidence cap 0.60 is applied at findings
    elif n <= 5:
        tag = "prior_assisted"
    else:
        tag = ""
    return Baseline(center=center, scale=scale, n=n, prior_weight=prior_weight, z=z, tag=tag)


